function drawMinimap(){let h='<svg viewBox="0 0 2850 2570" aria-hidden="true">';Object.values(DATA.regions).forEach(r=>{h+=`<path d="${regionPath(r)}" fill="${r.color}" opacity=".23"/>`});DATA.systems.forEach(s=>h+=`<circle cx="${s.x}" cy="${s.y}" r="${s.major?29:17}" fill="${color(s)}" opacity=".7"/>`);h+=`<rect x="${vb.x}" y="${vb.y}" width="${vb.w}" height="${vb.h}" fill="none" stroke="#e0c485" stroke-width="26"/></svg>`;$('minimap').innerHTML=h}
